$view=$_GET['view']??'list';$editId=(int)($_GET['id']??0);$categories=[];try{$r=$conn->query('SELECT id,name,slug FROM categories ORDER BY id ASC');if($r)$categories=$r->fetch_all(MYSQLI_ASSOC);}catch(Throwable $e){error_log($e->getMessage());}
$assignableCategories=array_values(array_filter($categories,static fn($c)=>(string)($c['slug']??'')!=='all'));
