$search=trim($_GET['search']??'');$category=(int)($_GET['category']??0);$page=max(1,(int)($_GET['page']??1));$limit=10;$offset=($page-1)*$limit;$posts=[];$total=0;
if($view==='list'){try{$where=[];$types='';$vals=[];if($search!==''){$where[]='(p.title LIKE ? OR p.excerpt LIKE ? OR p.author_name LIKE ?)';$like='%'.$search.'%';$types.='sss';array_push($vals,$like,$like,$like);}if($category>0){$where[]='p.category_id=?';$types.='i';$vals[]=$category;}$ws=$where?' WHERE '.implode(' AND ',$where):'';$sql="SELECT COUNT(*) c FROM blog_posts p".$ws;$st=$conn->prepare($sql);if($types)$st->bind_param($types,...$vals);$st->execute();$total=(int)$st->get_result()->fetch_assoc()['c'];$st->close();$sql="SELECT p.*,c.name category_name FROM blog_posts p LEFT JOIN categories c ON c.id=p.category_id".$ws." ORDER BY COALESCE(p.post_date,DATE(p.created_at)) DESC,p.id DESC LIMIT ? OFFSET ?";$st=$conn->prepare($sql);$t2=$types.'ii';$v2=array_merge($vals,[$limit,$offset]);$st->bind_param($t2,...$v2);$st->execute();$posts=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();}catch(Throwable $e){error_log('Blogs: '.$e->getMessage());}}
$pages=max(1,(int)ceil($total/$limit));
?>
